const PAIRS = new Map([[")", "("], ["]", "["], ["}", "{"]]);

function isBalanced(s: string): boolean {
  const stack: string[] = [];
  for (const ch of s) {
    if ("([{".includes(ch)) stack.push(ch);
    else if (PAIRS.has(ch) && stack.pop() !== PAIRS.get(ch)) {
      return false;
    }
  }
  return stack.length === 0;
}

