type ListNode = { value: string; next: ListNode | null };

const c: ListNode = { value: "Note C", next: null };
const b: ListNode = { value: "Note B", next: c };
let head: ListNode = { value: "Note A", next: b };

function reverse(head: ListNode | null) {
  let prev: ListNode | null = null;
  let curr = head;
  while (curr) {
    const next = curr.next; // save first
    curr.next = prev;       // flip
    prev = curr;            // step forward
    curr = next;
  }
  return prev; // the new head
}

function fitHistory(msgs: Msg[], budget: number) {
  let total = msgs.reduce((sum, m) => sum + m.tokens, 0);
  let start = 0;
  while (total > budget && start < msgs.length - 1) {
    total -= msgs[start].tokens; // drop the oldest
    start++;
  }
  return msgs.slice(start); // always keep the newest
}
